/* The Plus/4 video DIN (CN7) differs from the C16 one: pins 7 and 8 are both unconnected. */
const PLUS4_VIDEO = {
  ...CBM264_PORTS.find(c => c.id === 'c16-video'),
  id: 'plus4-video',
  verifiedAgainst: 'Plus/4 térkép connector map (CN7 Video); Plus/4 Service Manual 314001-04 schematic, CN7',
  summary: 'CN7, the 8-pin video DIN fed by the RF modulator: separate LUM and COLOR (S-Video with a simple cable), composite and audio. Pins 7 and 8 are not connected on the Plus/4; the C16 has +5 V on pin 8, so a C16 cable that draws power from pin 8 gets none here.',
  pins: CBM264_PORTS.find(c => c.id === 'c16-video').pins.map(p => (p.n === 8 ? { n: 8, name: 'NC', type: 'nc', desc: 'No connection on the Plus/4 (the C16 has +5 V here).' } : (p.n === 1 || p.n === 4 ? (({ expect, ...rest }) => rest)(p) : p))),
  sources: [
    { label: 'Plus/4 térkép connector map, CN7 Video (pins 7 and 8 N.C.)', url: 'http://www.zimmers.net/anonftp/pub/cbm/schematics/computers/plus4/connectors-2.jpg' },
    { label: 'Plus/4 Service Manual 314001-04, schematic with CN7 (pins 7 and 8 to N.C.), PDF p. 21', url: 'http://www.zimmers.net/anonftp/pub/cbm/schematics/computers/plus4/Plus_4_Service_Manual_314001-04_%281984_Oct%29.pdf#page=21' },
  ],
};
/* Plus/4 copies of the shared 264 ports: CN2 pin 1 is N.C., and the cassette and joystick routes on the C16 schematic are not proven for the Plus/4. */
const P4FIX = {
  'c16-iec': { 1: { n: 1, name: 'NC', type: 'nc', desc: 'Not connected on the Plus/4 (CN2 pin 1 N.C.; the C16 has /SRQ IN here).' } },
  'c16-cass': { 3: { n: 3, name: 'MOTOR', type: 'power', desc: 'Cassette motor supply.' }, 4: { n: 4, name: 'READ', type: 'io', desc: 'Tape read data.' }, 6: { n: 6, name: 'SENSE', type: 'io', desc: 'Cassette key sense.' } },
  'c16-joy': { 8: { n: 8, name: 'SELECT', type: 'ctrl', desc: 'Joystick select line.' } },
};
const plus4Port = c => (P4FIX[c.id] ? { ...c, pins: c.pins.map(p => P4FIX[c.id][p.n] || p) } : c);
const CBM264_TESTPOINTS = [
  { tp: 'Master clock', where: 'TED pin 14', expect: '17.734 MHz PAL / 14.318 MHz NTSC (TED manual: ±70 ppm)' },
  { tp: 'CPU clock', where: 'TED pin 12 → 7501 pin 1', expect: '0.89 MHz NTSC single clock; doubles to 1.79 MHz during blanking' },
  { tp: 'Reset', where: '7501 pin 40', expect: 'LOW ~0.3 s after power-on, then HIGH' },
  { tp: 'DRAM strobes', where: 'TED pins 10, 11', expect: '/RAS pulsing continuously; /CAS only on DRAM accesses (not in RAS-only refresh)' },
  { tp: 'Video', where: 'TED pin 23 LUM', expect: '~1 V p-p with sync' },
  { tp: 'TED temperature', where: 'TED body', expect: 'Hot to touch is normal; fit a heatsink' },
];
const CBM264_TP = scope => CBM264_TESTPOINTS.map(t => (t.where === 'TED pin 14' ? { ...t, scope } : t));
/* Disk drives (1541, 1571, 1581): shared source links and pad helpers. */
