/* Serial bus pair: two identical 6-pin DIN sockets wired in parallel, female on the drive. */
const CBMD_IEC = (id, where, extra, sources) => ({
  id, name: 'Serial bus (IEC) in / out', kind: 'DIN-6 × 2 (wired in parallel)', geo: 'din6', gender: 'female',
  verify: false,
  verifiedAgainst: sources[0].label,
  summary: `${where} Two identical sockets wired pin for pin: one goes to the computer, the other daisy-chains the next drive or printer. ${extra}`,
  pins: [
    id === '1581-iec'
      ? { n: 1, name: 'FAST CLK (/SRQ)', type: 'serial', desc: 'Fast-serial clock on the /SRQ line, passed between the two sockets. Driven by U11 (7407) pin 6 and pulled up to +5 V on the drive by R26 (RP1-13, 1 kΩ) (schematic 252380 sheet 3).', expect: 'About +5 V idle, even with no computer connected (R26 pull-up)' }
      : { n: 1, name: '/SRQ', type: 'serial', desc: `Service request, passed between the two sockets.${id === '1571-iec' ? ' The 1571 uses it as the fast-serial clock.' : ''}`, expect: 'About +5 V idle with the computer connected (the drive has no pull-up of its own)' },
    { n: 2, name: 'GND', type: 'ground', desc: 'Signal ground.', expect: '0 V' },
    { n: 3, name: 'ATN', type: 'serial', desc: id === '1581-iec' ? 'Attention from the computer. Through U9/U7 to the 8520 CIA /FLAG (pin 24) and PB7 (pin 17); the CIA interrupts the CPU (IRQ, pin 21).' : 'Attention from the computer. Interrupts the drive CPU through the serial VIA CA1.', expect: 'About +5 V idle; LOW while the computer addresses the bus' },
    { n: 4, name: 'CLK', type: 'serial', desc: 'Serial clock, open collector in and out.', expect: 'About +5 V idle' },
    { n: 5, name: 'DATA', type: 'serial', desc: 'Serial data, open collector in and out.', expect: 'About +5 V idle; LOW when asserted' },
    { n: 6, name: '/RESET', type: 'ctrl', desc: 'Reset from the computer. LOW resets the drive.', expect: '+5 V; LOW during a computer reset' },
  ],
  sources,
  terms: ['iec', 'open-drain'],
});
