        'Board 250471: 6502 U1, DOS ROM U2 (socketed), 8K RAM U3, WD1770/1772 U4, 8520 U5.',
        'Most faults are the brick: measure +5 V loaded while the drive works.',
        'Green LED stuck on after power-up: DOS ROM U2 first, then 8520 U5 and 74LS14 U9.',
        'Never refit the 4-wire mechanism power cable without checking its orientation: reversed, it kills the mechanism.',
        'Power-up with no disk: both LEDs on, stepper "burps" back to track 1, green goes out after about 2 s. No spindle without a disk (Carlsen).',
